using SanSo.Import;
namespace SanSo.Api.V2;
public static class ExtendedEndpointComposition
{
 private static readonly CommerceFileImporter Importer=new(new ImportRegistry());
 public static WebApplication MapIdentity(this WebApplication app){SanSo.Api.IdentityEndpoints.MapIdentity(app);app.MapPost("/api/imports/preview",async(HttpRequest request,CancellationToken ct)=>{if(!request.HasFormContentType)return Results.BadRequest(new{code="MULTIPART_REQUIRED"});var form=await request.ReadFormAsync(ct);var file=form.Files.GetFile("file");if(file is null)return Results.BadRequest(new{code="FILE_REQUIRED"});if(file.Length>10*1024*1024)return Results.BadRequest(new{code="FILE_TOO_LARGE"});var tenant=request.HttpContext.Items["TenantId"]as string??request.Headers["X-Tenant-Id"].FirstOrDefault()??"tenant-an-nhien";await using var stream=file.OpenReadStream();try{ImportPreview preview;var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(ext==".csv"&&file.ContentType is"text/csv"or"application/csv"or"application/vnd.ms-excel"or"application/octet-stream")preview=Importer.PreviewCsv(tenant,stream);else if(ext==".xlsx"&&file.ContentType is"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"or"application/octet-stream")preview=Importer.PreviewXlsx(tenant,stream);else return Results.BadRequest(new{code="UNSUPPORTED_FILE_TYPE"});return Results.Ok(preview);}catch(DecoderFallbackException){return Results.BadRequest(new{code="ENCODING_INVALID",hint="Save CSV as UTF-8"});}catch(InvalidDataException e){return Results.BadRequest(new{code=e.Message});}});return app;}
}
